	function M.priceFor(model, record)
		local id = tostring(model or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
		if id == "" then return nil end

		-- 1. Free/local providers always cost $0.00
		if record then
			if record.preset == "ollama" or record.preset == "lmstudio" then
				return { 0, 0 }
			end
			local base = tostring(record.baseUrl or ""):lower()
			if base:find("localhost", 1, true) or base:find("127.0.0.1", 1, true) then
				return { 0, 0 }
			end
			local registry = env.require("provider/registry")
			if registry and registry.isOpencode and registry.isOpencode(record) then
				if id == "big-pickle" or id == "minipickle" or id:find(":free", 1, true) then
					return { 0, 0 }
				end
			end
		end

		-- 2. Exact match on raw ID
		if PRICES[id] then return PRICES[id] end

		-- 3. Normalized match without provider prefix (e.g. openai/gpt-4o -> gpt-4o)
		local bare = id:gsub("^[^/]+/", "")
		if PRICES[bare] then return PRICES[bare] end

		-- 4. Dot-to-dash variations (e.g. claude-3.5-sonnet -> claude-3-5-sonnet)
		local dashed = id:gsub("%.", "-")
		if PRICES[dashed] then return PRICES[dashed] end
		local bareDashed = bare:gsub("%.", "-")
		if PRICES[bareDashed] then return PRICES[bareDashed] end

		-- 5. Longest prefix matching for dated snapshots (e.g. gpt-4o-2024-11-20 -> gpt-4o)
		local best, bestLen = nil, 0
		for prefix, price in pairs(PRICES) do
			if #prefix >= 4 and id:find(prefix, 1, true) and #prefix > bestLen then
				best, bestLen = price, #prefix
			end
		end
		if best then return best end

		for prefix, price in pairs(PRICES) do
			if #prefix >= 4 and bare:find(prefix, 1, true) and #prefix > bestLen then
				best, bestLen = price, #prefix
			end
		end
		return best
	end

	M.PRICES = PRICES
	return M
end
